class DoublingSpinBox(QtWidgets.QSpinBox):
    def __init__(self, parent=None):
        super(DoublingSpinBox, self).__init__(parent)
        self.setRange(8, 32768)  # Set an appropriate range for the spinbox

    def stepBy(self, steps):
        current_value = self.value()
        if steps > 0:
            new_value = current_value * 2
        elif steps < 0:
            new_value = max(8, current_value // 2)  # Ensure it doesn't go below 8
        self.setValue(new_value)

class QTextEditLoggerTrain(logging.Handler, QtCore.QObject):

    log_signal = QtCore.pyqtSignal(str)

    def __init__(self):

        logging.Handler.__init__(self)

        QtCore.QObject.__init__(self)

    def emit(self, record):

        self.msg = self.format(record)

        self.log_signal.emit(self.msg)


