    def create_canvas(self, figure, label):
        
        # Create a canvas to render the figure
        self.canvas = FigureCanvasQTAgg(figure)
        # Remove previous items from the scene
        label.clear()
        self.canvas.draw()

        size = self.canvas.size()
        width, height = size.width(), size.height()
        img = QtGui.QImage(self.canvas.buffer_rgba(), width, height, QtGui.QImage.Format.Format_RGBA8888)
        pixmap = QtGui.QPixmap(img)

        label.setPixmap(pixmap.scaled(512, 512, QtCore.Qt.AspectRatioMode.KeepAspectRatio, 
                                           QtCore.Qt.TransformationMode.SmoothTransformation))
        label.setAlignment(QtCore.Qt.AlignmentFlag.AlignTop | QtCore.Qt.AlignmentFlag.AlignLeft)


    def plot_train_dataset(self):

        if self.dataset_dicts_train != None:

            for d in random.sample(self.dataset_dicts_train, 1):

                img = cv2.imread(d["file_name"])

                visualizer = Visualizer(img[:, :, ::-1], metadata=self.nuts_metadata_train, scale=1)

                vis = visualizer.draw_dataset_dict(d)

                final_image = vis.get_image()[:, :, ::-1]

                self.figure = Figure(facecolor='#F0F0F0', dpi=500)

                self.figure.tight_layout()

                axes = self.figure.gca()

                axes.set_title("Training Data Sample")

                axes.axis("off")

                axes.imshow(final_image, cmap='gray')

                self.create_canvas(self.figure, self.labelVisualiseTrainingData)

    def select_dataset_train_path(self):

        file_dialog = QtWidgets.QFileDialog(directory='./')

        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.Directory)

        self.file_dialog_dataset_train = file_dialog.exec()
        
        if self.file_dialog_dataset_train == QtWidgets.QFileDialog.DialogCode.Accepted:

            self.path_dataset_train = file_dialog.selectedFiles()[0]


    def select_dataset_test_path(self):

        file_dialog = QtWidgets.QFileDialog(directory='./')

        file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.Directory)

        self.file_dialog_dataset_test = file_dialog.exec()
        
        if self.file_dialog_dataset_test == QtWidgets.QFileDialog.DialogCode.Accepted:

            self.path_dataset_test = file_dialog.selectedFiles()[0]


    def register_dataset_train(self):

        if self.file_dialog_dataset_train == QtWidgets.QFileDialog.DialogCode.Accepted:
            
            self.labelTrainingLog.clear()

            try:

                self.count +=1 

                self.dataset_train_name = "my_dataset_train_" + str(self.count)

                # dataset name, json path, images path
                register_coco_instances(self.dataset_train_name, {}, self.path_dataset_train + "/instances_train.json" , self.path_dataset_train) 
                              
                self.nuts_metadata_train = MetadataCatalog.get(self.dataset_train_name)
                
                self.dataset_dicts_train = DatasetCatalog.get(self.dataset_train_name)

                self.labelTrainingLog.appendPlainText("Dataset registerd.")

            except Exception as e:

                self.labelTrainingLog.clear()

                self.labelTrainingLog.appendPlainText("Error when registering a new dataset.")

                self.labelTrainingLog.appendPlainText(str(e))

    def register_dataset_test(self):

        if self.file_dialog_dataset_test == QtWidgets.QFileDialog.DialogCode.Accepted:

            try: 

                self.count +=1 

                self.dataset_test_name = "my_dataset_test_" + str(self.count)

                # dataset name, json path, images path
                register_coco_instances(self.dataset_test_name, {}, self.path_dataset_test  + "/instances_val.json", self.path_dataset_test) 

                nuts_metadata = MetadataCatalog.get(self.dataset_test_name)
                
                dataset_dicts = DatasetCatalog.get(self.dataset_test_name)

            except Exception as e:

                self.labelTrainingLog.clear()

                self.labelTrainingLog.appendPlainText("Error when registering a new dataset.")

                self.labelTrainingLog.appendPlainText(str(e))

    def train_model_thread(self):

        try: 

            self.import_thread = TrainModelThread(self.labelTrainingLog, self.dataset_train_name, self.dataset_test_name, self.spinBoxImgSize, self.spinBoxNumOfClasses, self.comboBoxDevice,
                                              self.spinBoxBatchSize, self.doubleSpinBoxLR, self.comboBoxModelWeights, self.spinBoxMaxIter, self.spinBoxROIBS)

            self.text_edit_handler.log_signal.connect(self.update_log_label)

            # Start thread
            self.import_thread.start()

        except Exception as e:

            self.labelTrainingLog.appendPlainText("Something went wrong.")

            self.labelTrainingLog.appendPlainText(str(e))

            
    def update_log_label(self, msg):

        self.labelTrainingLog.appendPlainText(msg)

    def check_selection(self):
        
        selected1 = self.comboBoxDevice.currentText()

        selected2 = self.dataset_train_name

        if (selected1 == "") or (selected2 == None):

            missing_fields = []
            
            if selected1 == "":

                missing_fields.append("Missing Device Option")

            if selected2 == None:

                missing_fields.append("Missing Train Dataset Path")

            error_message = "- " + "\n".join(missing_fields)
            
            QtWidgets.QMessageBox.warning(self, "Selection Error", error_message)
        
        else:

            self.train_model_thread()

    def open_input_dialog(self):

        dialog = InputDialog(self.spinBoxBatchSize, self.doubleSpinBoxLR, self.comboBoxModelWeights, self.spinBoxMaxIter, self.spinBoxROIBS)

        if dialog.exec() == QtWidgets.QDialog.DialogCode.Accepted:

            self.spinBoxBatchSize, self.doubleSpinBoxLR, self.comboBoxModelWeights, \
                self.spinBoxMaxIter, self.spinBoxROIBS = dialog.getValues()
            
            
    def setup_logging_train(self):

        try:

            # Create a QTextEditLogger handler
            self.text_edit_handler = QTextEditLoggerTrain()

            # Set up the root logger
            root_logger = logging.getLogger()
            root_logger.addHandler(self.text_edit_handler)

            # Set up the Detectron2 loggers
            # Configure Detectron2 loggers
            for name in ['detectron2', 'fvcore', 'd2']:
                d2_logger = logging.getLogger(name)
                d2_logger.setLevel(logging.INFO)
                #d2_logger.propagate = True  # Ensure propagation
                d2_logger.addHandler(self.text_edit_handler)

            # d2_logger = logging.getLogger('detectron2')
            # d2_logger.addHandler(self.text_edit_handler)

        except Exception as e:

            print("Something went wrong.")

            print(str(e))

